INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(735157, 78709, 3569, '<td valign="top">Nice click beetle.</td>', 'Nice click beetle.', '2004-05-25 13:25:49.000000', NULL, 1),
(735163, 78845, 3569, '<td valign="top">And even on a turtle shell.  Nice capture</td>', 'And even on a turtle shell.  Nice capture', '2004-05-25 13:28:35.000000', NULL, 1),
(735166, 78785, 3569, '<td valign="top">Great interpretation and shot...</td>', 'Great interpretation and shot...', '2004-05-25 13:29:22.000000', NULL, 1),
(735171, 78481, 327, '<td valign="top">Very funny. 9 from me. Love it.</td>', 'Very funny. 9 from me. Love it.', '2004-05-25 13:30:34.000000', NULL, 1),
(735173, 78588, 327, '<td valign="top">Stunning shot. Very ornate building, like the tones.</td>', 'Stunning shot. Very ornate building, like the tones.', '2004-05-25 13:31:17.000000', NULL, 1),
(735200, 78709, 22186, '<td valign="top">What''s he lookin'' at?! Who''s unusual viewpoint?Cool pic. But that bug has a staring problem.</td>', 'What''s he lookin'' at?! Who''s unusual viewpoint?Cool pic. But that bug has a staring problem.', '2004-05-25 13:47:52.000000', NULL, 1),
(735214, 78296, 15920, '<td valign="top">Very clever, and very well done (the photography is very good, but getting a teenager to help you is perhaps even more impressive.)  The lighting is perfect, the model has a great expression, and the DOF is excellent.  Apparently, this needs a 10 from me.</td>', 'Very clever, and very well done (the photography is very good, but getting a teenager to help you is perhaps even more impressive.)  The lighting is perfect, the model has a great expression, and the DOF is excellent.  Apparently, this needs a 10 from me.', '2004-05-25 13:55:35.000000', NULL, 1),
(735217, 78169, 15920, '<td valign="top">Very good, but perhaps a bit over sharpened?</td>', 'Very good, but perhaps a bit over sharpened?', '2004-05-25 13:57:37.000000', NULL, 1),
(735230, 78696, 17166, '<td valign="top">Definately an interesting viewpoint that conveys a feeling of massive power.  I find the sky at the left edge a bit distracting and think this photo would work better with it cropped out.</td>', 'Definately an interesting viewpoint that conveys a feeling of massive power.  I find the sky at the left edge a bit distracting and think this photo would work better with it cropped out.', '2004-05-25 14:12:58.000000', NULL, 1),
(735238, 78828, 17166, '<td valign="top">Good picture - like the bright, saturated primary colors and it''s a great viewpoint.  I think this could be a fantastic picture if it were cropped a lot tighter - like just outside his hands, and if it were in portrait instead of landscape format.</td>', 'Good picture - like the bright, saturated primary colors and it''s a great viewpoint.  I think this could be a fantastic picture if it were cropped a lot tighter - like just outside his hands, and if it were in portrait instead of landscape format.', '2004-05-25 14:16:45.000000', NULL, 1),
(735247, 78097, 17166, '<td valign="top">Wow - fantastic fraiming.  Nice catch!  I get the feeling this could be improved if the fountain wasn''t so priminant but I''m not quite sure how to go about it - maybe by cloning out the lights?  Still, one of my favourites from this challenge.</td>', 'Wow - fantastic fraiming.  Nice catch!  I get the feeling this could be improved if the fountain wasn''t so priminant but I''m not quite sure how to go about it - maybe by cloning out the lights?  Still, one of my favourites from this challenge.', '2004-05-25 14:20:20.000000', NULL, 1),
(735296, 78601, 11895, '<td valign="top">I really like this but maybe witout the tilt, or with less tilt would have been better</td>', 'I really like this but maybe witout the tilt, or with less tilt would have been better', '2004-05-25 14:51:10.000000', NULL, 1),
(735297, 78816, 18403, '<td valign="top">I really like your bird photo, but there seems to be a loss of detail in the feathers around the neck.  Did you use a noise reduction filter?  If so, try selecting just the background for noise reduction and leave the subject areas with greater detail.  Jpeg compression can also make an image look ''muddy'' by smearing out fine details, especially when the compression process is repeated several times.</td>', 'I really like your bird photo, but there seems to be a loss of detail in the feathers around the neck.  Did you use a noise reduction filter?  If so, try selecting just the background for noise reduction and leave the subject areas with greater detail.  Jpeg compression can also make an image look ''muddy'' by smearing out fine details, especially when the compression process is repeated several times.', '2004-05-25 14:51:18.000000', NULL, 1),
(735300, 78650, 18403, '<td valign="top">For better results, don''t squint while sighting, take a deep breath and hold it as you squeeze the trigger. Nice shot!</td>', 'For better results, don''t squint while sighting, take a deep breath and hold it as you squeeze the trigger. Nice shot!', '2004-05-25 14:53:51.000000', NULL, 1),
(735302, 78276, 7322, '<td valign="top">I understand the idea behind the tilted format (bird''s freewheeling point of view) but I''m not sure it''s working with so much going on at the bottom. Perhaps if it were cropped to exclude some of the bottom portion? If you look at only the bottom half of the photo it is a very visually cluttered shot. The top half (from just above the light fixture) works a little better. I''m not a fan of tilted shots so I''m probably a bit biased.</td>', 'I understand the idea behind the tilted format (bird''s freewheeling point of view) but I''m not sure it''s working with so much going on at the bottom. Perhaps if it were cropped to exclude some of the bottom portion? If you look at only the bottom half of the photo it is a very visually cluttered shot. The top half (from just above the light fixture) works a little better. I''m not a fan of tilted shots so I''m probably a bit biased.', '2004-05-25 14:54:37.000000', NULL, 1),
(735307, 78028, 7322, '<td valign="top">Interesting idea. It might have been more successful with an infinite focus so the mouth isn''t blurred out so much. The printing on the bottle has a way of drawing the eye.</td>', 'Interesting idea. It might have been more successful with an infinite focus so the mouth isn''t blurred out so much. The printing on the bottle has a way of drawing the eye.', '2004-05-25 14:55:49.000000', NULL, 1),
(735311, 78563, 7322, '<td valign="top">Nice strong planes and lines. It''s a bit lacking in contrast. I wonder if it would have worked better in color against a blue sky?  I like the tiny sun rays peeping over the rim of the round thing.</td>', 'Nice strong planes and lines. It''s a bit lacking in contrast. I wonder if it would have worked better in color against a blue sky?  I like the tiny sun rays peeping over the rim of the round thing.', '2004-05-25 14:57:16.000000', NULL, 1),
(735312, 78485, 18403, '<td valign="top">I like the clean, unculttered appearance!  Low angle of the sun helps also.  The boat may be an unnecessary distraction, but does add some interest to the photo.</td>', 'I like the clean, unculttered appearance!  Low angle of the sun helps also.  The boat may be an unnecessary distraction, but does add some interest to the photo.', '2004-05-25 14:57:17.000000', NULL, 1),
(735316, 78563, 18403, '<td valign="top">Composition is nice, but the image seems to be grainy, particularly in the sky areas.  Try selecting those areas and using a gaussian blur to clean up the noise.  A higher contrast would help as well.</td>', 'Composition is nice, but the image seems to be grainy, particularly in the sky areas.  Try selecting those areas and using a gaussian blur to clean up the noise.  A higher contrast would help as well.', '2004-05-25 15:01:52.000000', NULL, 1),
(735328, 78581, 18403, '<td valign="top">A little bit more of the eye through the grass would be more appealing with the focus shifted to the point of the eye.</td>', 'A little bit more of the eye through the grass would be more appealing with the focus shifted to the point of the eye.', '2004-05-25 15:08:03.000000', NULL, 1),
(735329, 78793, 7322, '<td valign="top">This a nice macro portrait of an eye but I don''t see the unusual viewpoint. It is a pretty direct viewpoint, actually. I suppose one could argue that you were unusually close to the subject but that would be stretching the notion, in my opinion.</td>', 'This a nice macro portrait of an eye but I don''t see the unusual viewpoint. It is a pretty direct viewpoint, actually. I suppose one could argue that you were unusually close to the subject but that would be stretching the notion, in my opinion.', '2004-05-25 15:08:54.000000', NULL, 1),
(735334, 77389, 18403, '<td valign="top">This aspect of the child''s face does not appeal to me.  Maybe would work better if the camera was more to one side.</td>', 'This aspect of the child''s face does not appeal to me.  Maybe would work better if the camera was more to one side.', '2004-05-25 15:11:19.000000', NULL, 1),
(735367, 78209, 18403, '<td valign="top">Lots of potential, but needs better lighting!</td>', 'Lots of potential, but needs better lighting!', '2004-05-25 15:33:33.000000', NULL, 1),
(735369, 78285, 18403, '<td valign="top">Love the expression on the critter''s face!</td>', 'Love the expression on the critter''s face!', '2004-05-25 15:35:29.000000', NULL, 1),
(735392, 78119, 10918, '<td valign="top">I''d be willing to bet this makes the top three. Awesome, awesome shot.</td>', 'I''d be willing to bet this makes the top three. Awesome, awesome shot.', '2004-05-25 16:21:30.000000', NULL, 1),
(735400, 78324, 13136, '<td valign="top">Good abstract.</td>', 'Good abstract.', '2004-05-25 16:30:36.000000', NULL, 1),
(735402, 78563, 13136, '<td valign="top">Good view. It could use a bit more contrast IMO. I like the reflection off the right sid eof the circle.</td>', 'Good view. It could use a bit more contrast IMO. I like the reflection off the right sid eof the circle.', '2004-05-25 16:31:55.000000', NULL, 1),
(735403, 78581, 13136, '<td valign="top">Good idea. Too difficult to figure what is in the background. Makes me feel like I am missing something.</td>', 'Good idea. Too difficult to figure what is in the background. Makes me feel like I am missing something.', '2004-05-25 16:33:06.000000', NULL, 1),
(735404, 78319, 13136, '<td valign="top">Good concept. I like that the front of the bottle is lit, but not the person.</td>', 'Good concept. I like that the front of the bottle is lit, but not the person.', '2004-05-25 16:34:06.000000', NULL, 1),
(735426, 78831, 20018, '<td valign="top">really like how the color of the curtain runs into the mountain/trees</td>', 'really like how the color of the curtain runs into the mountain/trees', '2004-05-25 16:55:34.000000', NULL, 1),
(735430, 78324, 20018, '<td valign="top">nice , freaky view of the attack stealth bombers</td>', 'nice , freaky view of the attack stealth bombers', '2004-05-25 17:00:55.000000', NULL, 1),
(735434, 77436, 13136, '<td valign="top">Very nice composition and colors. Unfortunately the shot looks a bit hazy.</td>', 'Very nice composition and colors. Unfortunately the shot looks a bit hazy.', '2004-05-25 17:05:07.000000', NULL, 1),
(735438, 77367, 13136, '<td valign="top">Very cool how you caught the multiple flashes of the individual fireflies.</td>', 'Very cool how you caught the multiple flashes of the individual fireflies.', '2004-05-25 17:10:09.000000', NULL, 1),
(735456, 78729, 20018, '<td valign="top">like the way half of the face is hidden by the grass, seems a little washed out in areas or just maybe too much light/flash contrast.  not sure i like the upside down treatment, with the straight on look of the subject I''m thinking the perspective should be more straight on. I wish we had more challenges that led to photographing people more than objects with macros lenses. good job</td>', 'like the way half of the face is hidden by the grass, seems a little washed out in areas or just maybe too much light/flash contrast.  not sure i like the upside down treatment, with the straight on look of the subject I''m thinking the perspective should be more straight on. I wish we had more challenges that led to photographing people more than objects with macros lenses. good job', '2004-05-25 17:25:29.000000', NULL, 1),
(735460, 78688, 20018, '<td valign="top">like the attitude here, would like to see more of the face though (closer to the cam)</td>', 'like the attitude here, would like to see more of the face though (closer to the cam)', '2004-05-25 17:26:57.000000', NULL, 1),
(735470, 78319, 20018, '<td valign="top">very surreal look to this one...</td>', 'very surreal look to this one...', '2004-05-25 17:30:35.000000', NULL, 1),
(735471, 77494, 3032, '<td valign="top">Did you use fill flash? If not, try it. You might scare them off, but before they run you at least have one succesful shot. The fill flash might bring out the details of the cows better and get a better balance with the bright (for the exposure) sky. Especially the black (bonte) one needs more detail. Set the exposure level to -1 to avoid blown out noses and a too flashy look.<br/> <br/>Composition is good (point of view, perspective, positioning, horizon positioning), the sky is great (a blue sky is very boring) and the colors are very natural strong and fresh.<br/></td>', 'Did you use fill flash? If not, try it. You might scare them off, but before they run you at least have one succesful shot. The fill flash might bring out the details of the cows better and get a better balance with the bright (for the exposure) sky. Especially the black (bonte) one needs more detail. Set the exposure level to -1 to avoid blown out noses and a too flashy look. Composition is good (point of view, perspective, positioning, horizon positioning), the sky is great (a blue sky is very boring) and the colors are very natural strong and fresh.', '2004-05-25 17:30:58.000000', NULL, 1),
(735472, 78845, 20018, '<td valign="top">sorry but the frog macros are killing me</td>', 'sorry but the frog macros are killing me', '2004-05-25 17:31:40.000000', NULL, 1),
(735480, 78135, 3032, '<td valign="top">Nice landscape. Good exposure &amp; composition, interesting subject matter &amp; sky. Colors could use a little bit of Velvia toning.</td>', 'Nice landscape. Good exposure & composition, interesting subject matter & sky. Colors could use a little bit of Velvia toning.', '2004-05-25 17:36:02.000000', NULL, 1),
(735486, 78689, 3032, '<td valign="top">Amazing how good this works with the background. I can''t say that I find the bark in the front very interesting, but somehow the whole package made me stop to take a longer look. :)</td>', 'Amazing how good this works with the background. I can''t say that I find the bark in the front very interesting, but somehow the whole package made me stop to take a longer look. :)', '2004-05-25 17:38:25.000000', NULL, 1),
(735490, 78563, 10047, '<td valign="top">A little overexposed. I might have tried darkening it.</td>', 'A little overexposed. I might have tried darkening it.', '2004-05-25 17:41:22.000000', NULL, 1),
(735495, 78689, 10047, '<td valign="top">Seems a little overexposed. I might have tried darkening it.</td>', 'Seems a little overexposed. I might have tried darkening it.', '2004-05-25 17:42:36.000000', NULL, 1),
(735500, 78563, 4562, '<td valign="top">awesome pic.....just a lil darker though.....7</td>', 'awesome pic.....just a lil darker though.....7', '2004-05-25 17:43:19.000000', NULL, 1),
(735502, 78285, 554, '<td valign="top">I loved this colt from the first photo I saw of it.....Beautiful shot. I''ts going to wallpaper right now.</td>', 'I loved this colt from the first photo I saw of it.....Beautiful shot. I''ts going to wallpaper right now.', '2004-05-25 17:43:39.000000', NULL, 1),
(735506, 77930, 3032, '<td valign="top">Great perspective (the gun almost comes out of my screen), interesting subjects and good composition. The look on the guy''s face is so cool and his posture makes it look movielike-realistic if you know what I mean.<br/>Also like the toning, makes it look classic. 9</td>', 'Great perspective (the gun almost comes out of my screen), interesting subjects and good composition. The look on the guy''s face is so cool and his posture makes it look movielike-realistic if you know what I mean.Also like the toning, makes it look classic. 9', '2004-05-25 17:44:13.000000', NULL, 1),
(735507, 78064, 4562, '<td valign="top">nice...like the cloud contrast</td>', 'nice...like the cloud contrast', '2004-05-25 17:44:56.000000', NULL, 1),
(735510, 78135, 10047, '<td valign="top">Nicely done. The stables seem to pop well against the background.</td>', 'Nicely done. The stables seem to pop well against the background.', '2004-05-25 17:45:36.000000', NULL, 1),
(735514, 78785, 10047, '<td valign="top">Creative and funny. Color, contrast, and clarity are excellent.</td>', 'Creative and funny. Color, contrast, and clarity are excellent.', '2004-05-25 17:46:46.000000', NULL, 1),
(735517, 77930, 4562, '<td valign="top">cool....do you have one with the focus the other way though??.....6</td>', 'cool....do you have one with the focus the other way though??.....6', '2004-05-25 17:47:32.000000', NULL, 1),
(735538, 78461, 4562, '<td valign="top">great pis.....i feel the deepness....7</td>', 'great pis.....i feel the deepness....7', '2004-05-25 17:52:35.000000', NULL, 1),
(735566, 78597, 14089, '<td valign="top">The white corners are distracting from what has the potential to be a nice photo.  I like your concept.</td>', 'The white corners are distracting from what has the potential to be a nice photo.  I like your concept.', '2004-05-25 18:04:43.000000', NULL, 1),
(735570, 78630, 14089, '<td valign="top">I don''t much care for the angle this photo is presented at, but if you were to rotate it 45 degrees CCW and crop it I think it would be a magnificent photo.</td>', 'I don''t much care for the angle this photo is presented at, but if you were to rotate it 45 degrees CCW and crop it I think it would be a magnificent photo.', '2004-05-25 18:06:41.000000', NULL, 1),
(735577, 78905, 14089, '<td valign="top">Excellent shot.  I really appreciate the shapes you have created with your positive/negative space.</td>', 'Excellent shot.  I really appreciate the shapes you have created with your positive/negative space.', '2004-05-25 18:08:40.000000', NULL, 1),
(735579, 78735, 14089, '<td valign="top">Fabulous display of proportion.</td>', 'Fabulous display of proportion.', '2004-05-25 18:09:03.000000', NULL, 1),
(735581, 77672, 14089, '<td valign="top">Hard to tell what I am looking at here.</td>', 'Hard to tell what I am looking at here.', '2004-05-25 18:09:37.000000', NULL, 1),
(735585, 78220, 14089, '<td valign="top">Good use of long exposure, and a nice composition as well.</td>', 'Good use of long exposure, and a nice composition as well.', '2004-05-25 18:10:51.000000', NULL, 1),
(735592, 78816, 3569, '<td valign="top">beautiful peregrine.  Did you try a bit more contrast to bring out the nice barring on the breast.</td>', 'beautiful peregrine.  Did you try a bit more contrast to bring out the nice barring on the breast.', '2004-05-25 18:13:30.000000', NULL, 1),
(735598, 78732, 3569, '<td valign="top">cool catepillar.  good lighting.</td>', 'cool catepillar.  good lighting.', '2004-05-25 18:15:47.000000', NULL, 1),
(735600, 78250, 3569, '<td valign="top">S slight more contrast and ya got a winner.</td>', 'S slight more contrast and ya got a winner.', '2004-05-25 18:16:25.000000', NULL, 1),
(735603, 78137, 3569, '<td valign="top">An orchid from the back, definitly an odd angle, but good.</td>', 'An orchid from the back, definitly an odd angle, but good.', '2004-05-25 18:18:45.000000', NULL, 1),
(735640, 78461, 20779, '<td valign="top">Wonderful luminosity. Great perpsective and choice of composition.</td>', 'Wonderful luminosity. Great perpsective and choice of composition.', '2004-05-25 18:45:31.000000', NULL, 1),
(735641, 78878, 20779, '<td valign="top">Amazing, of course.</td>', 'Amazing, of course.', '2004-05-25 18:46:08.000000', NULL, 1),
(735643, 78735, 20779, '<td valign="top">Would have been a great  one for "centered", too! Great composition and use of B &amp; W. 8.</td>', 'Would have been a great  one for "centered", too! Great composition and use of B & W. 8.', '2004-05-25 18:47:31.000000', NULL, 1),
(735646, 78539, 20779, '<td valign="top">Unique spin on a old favorite. Beautiful, lush color, also. Really enjoy this one.</td>', 'Unique spin on a old favorite. Beautiful, lush color, also. Really enjoy this one.', '2004-05-25 18:48:43.000000', NULL, 1),
(735649, 78588, 20779, '<td valign="top">Perfect, crisp, luminous. I</td>', 'Perfect, crisp, luminous. I', '2004-05-25 18:49:32.000000', NULL, 1),
(735651, 78334, 20779, '<td valign="top">This one is one of my favorites. So simple; great lighting; perfect composition. It says a lot to me.</td>', 'This one is one of my favorites. So simple; great lighting; perfect composition. It says a lot to me.', '2004-05-25 18:51:03.000000', NULL, 1),
(735654, 78276, 20779, '<td valign="top">I think the tilt, cropping (?), and crisp color made what could have been ordinary, very stunning.</td>', 'I think the tilt, cropping (?), and crisp color made what could have been ordinary, very stunning.', '2004-05-25 18:51:55.000000', NULL, 1),
(735656, 78319, 20779, '<td valign="top">Thought of this, but you had the talent to execute it perfectly.</td>', 'Thought of this, but you had the talent to execute it perfectly.', '2004-05-25 18:53:00.000000', NULL, 1),
(735658, 78785, 20779, '<td valign="top">Well done!</td>', 'Well done!', '2004-05-25 18:53:38.000000', NULL, 1),
(735661, 78357, 20779, '<td valign="top">Great set-up and colors. Beautiful, crisp alignment.</td>', 'Great set-up and colors. Beautiful, crisp alignment.', '2004-05-25 18:54:44.000000', NULL, 1),
(735663, 77494, 20779, '<td valign="top">Almost surreal looking from the angle you shot it. Great color and clarity also!</td>', 'Almost surreal looking from the angle you shot it. Great color and clarity also!', '2004-05-25 18:55:44.000000', NULL, 1),
(735667, 77830, 20779, '<td valign="top">I like this shot a lot. I am wondering how it might look with a little of the dark cropped off or the balance re-set. It would be fun to play with at least!</td>', 'I like this shot a lot. I am wondering how it might look with a little of the dark cropped off or the balance re-set. It would be fun to play with at least!', '2004-05-25 18:58:17.000000', NULL, 1),
(735668, 78704, 20779, '<td valign="top">Great job . . . and still in perfect focus!</td>', 'Great job . . . and still in perfect focus!', '2004-05-25 18:58:51.000000', NULL, 1),
(735671, 78482, 20779, '<td valign="top">Perfect lighting, angle and capture. I don''t know if this was cropped much, but if so, I would like to see it with more background as comparison.</td>', 'Perfect lighting, angle and capture. I don''t know if this was cropped much, but if so, I would like to see it with more background as comparison.', '2004-05-25 19:00:07.000000', NULL, 1),
(735677, 78761, 20779, '<td valign="top">Beautiful, strong scenery. I think it would have been nice to have a little more depth and sharper focus, with a more pronounced subject of focus.</td>', 'Beautiful, strong scenery. I think it would have been nice to have a little more depth and sharper focus, with a more pronounced subject of focus.', '2004-05-25 19:03:04.000000', NULL, 1),
(735680, 78485, 15403, '<td valign="top">Interesting perspective.  The reflection makes the shot</td>', 'Interesting perspective.  The reflection makes the shot', '2004-05-25 19:04:44.000000', NULL, 1),
(735681, 78653, 20779, '<td valign="top">Due to the soft focus and haziness, not quite sure what I am seing (the band on top and to the left). Interesting use of soft focus.</td>', 'Due to the soft focus and haziness, not quite sure what I am seing (the band on top and to the left). Interesting use of soft focus.', '2004-05-25 19:05:16.000000', NULL, 1),
(735682, 78771, 15403, '<td valign="top">great idea.  I''m not sure how high the building is, but from this perspective, you could be 100 stories up.  Excellent in my eyes</td>', 'great idea.  I''m not sure how high the building is, but from this perspective, you could be 100 stories up.  Excellent in my eyes', '2004-05-25 19:05:28.000000', NULL, 1),
(735686, 78451, 15403, '<td valign="top">wonderfully thought out.  I would have liked it a little better if the foreground were focused, as opposed to the backfield, but nonetheless, a great shot...</td>', 'wonderfully thought out.  I would have liked it a little better if the foreground were focused, as opposed to the backfield, but nonetheless, a great shot...', '2004-05-25 19:06:48.000000', NULL, 1),
(735688, 77373, 20779, '<td valign="top">Great catch and good focus for this. I would have liked a little more contrast/brightening to the colors and a more off-center composition, I think.</td>', 'Great catch and good focus for this. I would have liked a little more contrast/brightening to the colors and a more off-center composition, I think.', '2004-05-25 19:07:35.000000', NULL, 1),
(735690, 78595, 15403, '<td valign="top">I really like this shot as is, but the two "cut off" heads is a bit distracting for me.</td>', 'I really like this shot as is, but the two "cut off" heads is a bit distracting for me.', '2004-05-25 19:08:33.000000', NULL, 1),
(735691, 78005, 15403, '<td valign="top">nice models!</td>', 'nice models!', '2004-05-25 19:09:03.000000', NULL, 1),
(735692, 78209, 20779, '<td valign="top">I find the image hard to look at, but I have tried to score it fairly outside of that. Good, tight macro. I would prefer less uniformity in the colors probably.</td>', 'I find the image hard to look at, but I have tried to score it fairly outside of that. Good, tight macro. I would prefer less uniformity in the colors probably.', '2004-05-25 19:09:16.000000', NULL, 1),
