(739797, 78028, 22300, '<td valign="top">Great color and perspective!</td>', 'Great color and perspective!', '2004-05-27 19:18:35.000000', NULL, 1),
(739798, 78097, 14255, '<td valign="top">The people at the top of this image spoil the shot. ould you have taken the shot again when they had moved on, or cropped the image to remove them.</td>', 'The people at the top of this image spoil the shot. ould you have taken the shot again when they had moved on, or cropped the image to remove them.', '2004-05-27 19:19:30.000000', NULL, 1),
(739801, 77930, 14255, '<td valign="top">I like the colouring of this shot, the bright white cloud at the side of the man in the picture looks out of place.</td>', 'I like the colouring of this shot, the bright white cloud at the side of the man in the picture looks out of place.', '2004-05-27 19:22:19.000000', NULL, 1),
(739803, 77559, 14255, '<td valign="top">The spider is brilliantly focused.</td>', 'The spider is brilliantly focused.', '2004-05-27 19:24:23.000000', NULL, 1),
(739807, 78276, 14255, '<td valign="top">I don''t like the angle that you have taken this shot. There is too much going on at the bottom of the picture. I would have cropped and used top 1/3rd of the tower with the 2 larger birds only.</td>', 'I don''t like the angle that you have taken this shot. There is too much going on at the bottom of the picture. I would have cropped and used top 1/3rd of the tower with the 2 larger birds only.', '2004-05-27 19:30:01.000000', NULL, 1),
(739814, 78335, 14255, '<td valign="top">Nice idea, Be aware of what you are taking, ie watch what is being reflected in the glasses though,  would have been better if you hadn''t got a cardboard box in front of the fireplace,  orange beaker in the middle of the carpet etc</td>', 'Nice idea, Be aware of what you are taking, ie watch what is being reflected in the glasses though,  would have been better if you hadn''t got a cardboard box in front of the fireplace,  orange beaker in the middle of the carpet etc', '2004-05-27 19:34:19.000000', NULL, 1),
(739816, 78263, 15768, '<td valign="top">nice grain effect. Pretty picture, pretty girl, pretty composition. However, not to unusual. 7</td>', 'nice grain effect. Pretty picture, pretty girl, pretty composition. However, not to unusual. 7', '2004-05-27 19:35:05.000000', NULL, 1),
(739818, 78319, 16982, '<td valign="top">This is a very nice, original shot.  Slight nitpick: maybe the rim of the waste bin could have its centre closer to the centre of the image?  Would also have done well in "Central Composition".</td>', 'This is a very nice, original shot.  Slight nitpick: maybe the rim of the waste bin could have its centre closer to the centre of the image?  Would also have done well in "Central Composition".', '2004-05-27 19:35:14.000000', NULL, 1),
