(741440, 78682, 17233, '<td valign="top">Very clean, crisp image with amazing light reflections. Great composition and definately unusual. Well done (10)</td>', 'Very clean, crisp image with amazing light reflections. Great composition and definately unusual. Well done (10)', '2004-05-29 02:32:46.000000', NULL, 1),
(741441, 78119, 17233, '<td valign="top">Beautifully worked image - DOF spot on and amazing reflection in the eye. Superb detail and perferct composition. Well done (10)</td>', 'Beautifully worked image - DOF spot on and amazing reflection in the eye. Superb detail and perferct composition. Well done (10)', '2004-05-29 02:35:11.000000', NULL, 1),
(741442, 78871, 17233, '<td valign="top">Great use of a simple, everyday subject. The composition and colours make this shot. I would like to see the DOF extend to the right a little more or perhaps all the way as this type of shot doesn''t need anything out of focus. Just a personal preference and not a criticism. Well done (9)</td>', 'Great use of a simple, everyday subject. The composition and colours make this shot. I would like to see the DOF extend to the right a little more or perhaps all the way as this type of shot doesn''t need anything out of focus. Just a personal preference and not a criticism. Well done (9)', '2004-05-29 02:38:51.000000', NULL, 1),
(741444, 77787, 17233, '<td valign="top">It is a speaker...it is an unusual viewpoint.....it has great definition and DOF and the exposure is spot on. Well done (10)</td>', 'It is a speaker...it is an unusual viewpoint.....it has great definition and DOF and the exposure is spot on. Well done (10)', '2004-05-29 02:39:55.000000', NULL, 1),
(741445, 78004, 17233, '<td valign="top">Great composition, great colours, great exposure. DOF is spot on - well done (9)</td>', 'Great composition, great colours, great exposure. DOF is spot on - well done (9)', '2004-05-29 02:41:27.000000', NULL, 1),
(741448, 78471, 17233, '<td valign="top">I love the diminitioning scale of the stools and the reflections in them. The exposure is very good in what seems to be a difficult lighting situation. DOF is also very good - well done (9)</td>', 'I love the diminitioning scale of the stools and the reflections in them. The exposure is very good in what seems to be a difficult lighting situation. DOF is also very good - well done (9)', '2004-05-29 02:44:19.000000', NULL, 1),
(741463, 78424, 18552, '<td valign="top">Very clear, well taken picture.</td>', 'Very clear, well taken picture.', '2004-05-29 03:46:08.000000', NULL, 1),
(741465, 78785, 18552, '<td valign="top">Very cute, well carried out idea for the challenge! I just love the look on the cat''s face.</td>', 'Very cute, well carried out idea for the challenge! I just love the look on the cat''s face.', '2004-05-29 03:47:09.000000', NULL, 1),
(741466, 78571, 18552, '<td valign="top">Very clever and unusual idea for the challenge.</td>', 'Very clever and unusual idea for the challenge.', '2004-05-29 03:48:29.000000', NULL, 1),
