(741471, 78590, 18552, '<td valign="top">Definately an unusual viewpoint! To my eyes, it might have been more effective if the camera appeared to be deeper in the can; also if the whole upper opening of the can had been visable. Color would have been nice, too.</td>', 'Definately an unusual viewpoint! To my eyes, it might have been more effective if the camera appeared to be deeper in the can; also if the whole upper opening of the can had been visable. Color would have been nice, too.', '2004-05-29 03:53:07.000000', NULL, 1),
(741472, 78254, 11078, '<td valign="top">Great clean image</td>', 'Great clean image', '2004-05-29 03:53:13.000000', NULL, 1),
(741473, 78451, 18552, '<td valign="top">One of my favorites in this challenge! It would have been nice if all the popcorn were in focus. However, you did a wonderful job on this photo.</td>', 'One of my favorites in this challenge! It would have been nice if all the popcorn were in focus. However, you did a wonderful job on this photo.', '2004-05-29 03:56:39.000000', NULL, 1),
(741476, 78481, 18552, '<td valign="top">Very clever and well taken pictue! I like the way the lady is blurred in the background.</td>', 'Very clever and well taken pictue! I like the way the lady is blurred in the background.', '2004-05-29 03:58:36.000000', NULL, 1),
(741477, 78220, 18552, '<td valign="top">Wonderful picture. Well composed, perfectly focused and great color. Can''t really tell you how you could improve as I like it just the way it is.</td>', 'Wonderful picture. Well composed, perfectly focused and great color. Can''t really tell you how you could improve as I like it just the way it is.', '2004-05-29 04:00:23.000000', NULL, 1),
(741480, 78319, 18552, '<td valign="top">Good job in difficult lighting conditions. It would have been great if somehow the whole opening of the trash can could have been included in the frame.</td>', 'Good job in difficult lighting conditions. It would have been great if somehow the whole opening of the trash can could have been included in the frame.', '2004-05-29 04:01:33.000000', NULL, 1),
(741481, 78878, 18552, '<td valign="top">Very unusual, indeed, to see a hummingbird at night. The whole thing is a bit noisy but that is probably hard to avoid.  The crop seems rather tight near the beak.</td>', 'Very unusual, indeed, to see a hummingbird at night. The whole thing is a bit noisy but that is probably hard to avoid.  The crop seems rather tight near the beak.', '2004-05-29 04:04:50.000000', NULL, 1),
(741482, 78276, 18552, '<td valign="top">Nice colorful picture. Just tipping something doesn''t really make it an unsual viewpoint, though.</td>', 'Nice colorful picture. Just tipping something doesn''t really make it an unsual viewpoint, though.', '2004-05-29 04:06:51.000000', NULL, 1),
(741497, 78634, 17033, '<td valign="top">not sure flipping the pic adds anything here</td>', 'not sure flipping the pic adds anything here', '2004-05-29 05:09:31.000000', NULL, 1),
(741498, 78064, 17033, '<td valign="top">lik the cloud/glass contrast</td>', 'lik the cloud/glass contrast', '2004-05-29 05:10:55.000000', NULL, 1),
