(741535, 78588, 17033, '<td valign="top">I like this perspective and did something similar (but of much lower quality) in the centred challenge. I guess you burnt out the sky...i think it works well here..focussing the eye on the detail of the building. well done</td>', 'I like this perspective and did something similar (but of much lower quality) in the centred challenge. I guess you burnt out the sky...i think it works well here..focussing the eye on the detail of the building. well done', '2004-05-29 06:19:01.000000', NULL, 1),
(741552, 78667, 19035, '<td valign="top">Great Picture - only distracting piece is the yellow flash on the oven door.  Very nice - 8.  Nice moustache too!</td>', 'Great Picture - only distracting piece is the yellow flash on the oven door.  Very nice - 8.  Nice moustache too!', '2004-05-29 07:33:14.000000', NULL, 1),
(741572, 78097, 15920, '<td valign="top">This is a great idea, but, the people on the next level down should be off camera.  At first glance, I thought the photo was about them, and it wasn''t until I stared a bit that I understood this scene and why the view was so unusual.</td>', 'This is a great idea, but, the people on the next level down should be off camera.  At first glance, I thought the photo was about them, and it wasn''t until I stared a bit that I understood this scene and why the view was so unusual.', '2004-05-29 08:09:53.000000', NULL, 1),
(741595, 78451, 8005, '<td valign="top">Cool. 7</td>', 'Cool. 7', '2004-05-29 08:46:16.000000', NULL, 1),
(741596, 77921, 8891, '<td valign="top">David you have got to stay out of the fridge at night....what have you been told.LOL! Very nice angle and you look like you''ve been caught....again!</td>', 'David you have got to stay out of the fridge at night....what have you been told.LOL! Very nice angle and you look like you''ve been caught....again!', '2004-05-29 08:46:40.000000', NULL, 1),
