(741598, 77903, 8891, '<td valign="top">Love the shadows and the mosaic like effect the net gives to this...the lighting at this angle gives a strange tint to the image which tends to look a bit oversaturated at least on my monitor.</td>', 'Love the shadows and the mosaic like effect the net gives to this...the lighting at this angle gives a strange tint to the image which tends to look a bit oversaturated at least on my monitor.', '2004-05-29 08:49:17.000000', NULL, 1),
(741599, 78377, 8891, '<td valign="top">Hey...who got daisy? Hmmmmm....must of have been at the castle? Don''t know. I know M. likes a good dapple so she should be happy that they are in the shot.</td>', 'Hey...who got daisy? Hmmmmm....must of have been at the castle? Don''t know. I know M. likes a good dapple so she should be happy that they are in the shot.', '2004-05-29 08:53:10.000000', NULL, 1),
(741611, 78816, 18191, '<td valign="top">I love the warm lighting.</td>', 'I love the warm lighting.', '2004-05-29 09:36:04.000000', NULL, 1),
(741612, 78362, 18191, '<td valign="top">Great DOF!</td>', 'Great DOF!', '2004-05-29 09:36:47.000000', NULL, 1),
(741625, 77641, 16488, '<td valign="top">Love this!  What a great use of perspective!  I have a feeling, though, that this would render better in print than on screen--on my (rather bright) monitor the foreground is almost lost, and so also the point.</td>', 'Love this!  What a great use of perspective!  I have a feeling, though, that this would render better in print than on screen--on my (rather bright) monitor the foreground is almost lost, and so also the point.', '2004-05-29 10:19:37.000000', NULL, 1),
(741627, 78838, 16488, '<td valign="top">Wow!  Perfect depth of field/ focus!  Lovely color and cropping!  Viewpoint enhances the subject by emphasizing just how far up (or down) the head of a dandelion is from a beetle''s point of view.  Extremely nice!</td>', 'Wow!  Perfect depth of field/ focus!  Lovely color and cropping!  Viewpoint enhances the subject by emphasizing just how far up (or down) the head of a dandelion is from a beetle''s point of view.  Extremely nice!', '2004-05-29 10:23:08.000000', NULL, 1),
(741638, 78588, 16488, '<td valign="top">Crisp!  Love the detail in the building.  Cropping gives an interesting geometry to the picture.  Only sorry I can''t see this blown up to wall size....</td>', 'Crisp!  Love the detail in the building.  Cropping gives an interesting geometry to the picture.  Only sorry I can''t see this blown up to wall size....', '2004-05-29 10:31:25.000000', NULL, 1),
