(742893, 78735, 18349, '<td valign="top">Great angle.  Love the B&amp;W treatment.</td>', 'Great angle.  Love the B&W treatment.', '2004-05-30 20:15:55.000000', NULL, 1),
(742894, 78785, 18349, '<td valign="top">Wonderful idea!   Sharpness on kitty''s eye is terrific.  Great job!</td>', 'Wonderful idea!   Sharpness on kitty''s eye is terrific.  Great job!', '2004-05-30 20:16:34.000000', NULL, 1),
