(742943, 78450, 489, '<td valign="top">I love the composition. The shot seems a little bit oversaturated on the blues.</td>', 'I love the composition. The shot seems a little bit oversaturated on the blues.', '2004-05-30 21:08:16.000000', NULL, 1),
