INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(742971, 78903, 489, '<td valign="top">Nice sunset, although I don''t think I would label it unusual.</td>', 'Nice sunset, although I don''t think I would label it unusual.', '2004-05-30 21:25:09.000000', NULL, 1),
(742972, 78367, 489, '<td valign="top">Interesting shot!</td>', 'Interesting shot!', '2004-05-30 21:25:56.000000', NULL, 1),
(742973, 77362, 489, '<td valign="top">I don''t know if I really get the selective desaturation here - I guess I am struggling to find the unusual viewpoint in this shot.</td>', 'I don''t know if I really get the selective desaturation here - I guess I am struggling to find the unusual viewpoint in this shot.', '2004-05-30 21:27:03.000000', NULL, 1),
(742974, 78771, 21500, '<td valign="top">great perspective - i love the feeling it gives you</td>', 'great perspective - i love the feeling it gives you', '2004-05-30 21:28:11.000000', NULL, 1),
(742976, 78878, 489, '<td valign="top">Interesting viewpoint for a hummingbird shot alright - don''t think I have EVER seen one from below. Well done.</td>', 'Interesting viewpoint for a hummingbird shot alright - don''t think I have EVER seen one from below. Well done.', '2004-05-30 21:28:22.000000', NULL, 1),
(742977, 78119, 21500, '<td valign="top">cool</td>', 'cool', '2004-05-30 21:28:48.000000', NULL, 1),
(742978, 78908, 489, '<td valign="top">I would LOVE to see this in color - the outfit looks like it had to be filled with it, and the sky as well? Not sure why you would go with B&amp;W on this shot.</td>', 'I would LOVE to see this in color - the outfit looks like it had to be filled with it, and the sky as well? Not sure why you would go with B&W on this shot.', '2004-05-30 21:29:41.000000', NULL, 1),
(742985, 78653, 489, '<td valign="top">Not sure I get what you were going for here - looks like a photoshop offset filter was applied, but I am not sure what that adds to the photo.</td>', 'Not sure I get what you were going for here - looks like a photoshop offset filter was applied, but I am not sure what that adds to the photo.', '2004-05-30 21:34:19.000000', NULL, 1),
(742986, 78667, 489, '<td valign="top">Heh heh... interesting angle.</td>', 'Heh heh... interesting angle.', '2004-05-30 21:34:33.000000', NULL, 1),
(742988, 78001, 489, '<td valign="top">Maybe not really that unusual, but I can''t deny that I like the composition and colors.</td>', 'Maybe not really that unusual, but I can''t deny that I like the composition and colors.', '2004-05-30 21:35:27.000000', NULL, 1),
(742992, 78735, 489, '<td valign="top">Nice geometry - the B&amp;W really works well here.</td>', 'Nice geometry - the B&W really works well here.', '2004-05-30 21:37:21.000000', NULL, 1),
(742994, 78704, 489, '<td valign="top">Great contrast - very crisp.</td>', 'Great contrast - very crisp.', '2004-05-30 21:38:06.000000', NULL, 1),
(742995, 78481, 489, '<td valign="top">Very humorous!</td>', 'Very humorous!', '2004-05-30 21:38:43.000000', NULL, 1),
(742997, 77494, 489, '<td valign="top">Fill flash would have taken this photo up several notches I think - especially for the cow on the right. I like the rest of the photo very much.</td>', 'Fill flash would have taken this photo up several notches I think - especially for the cow on the right. I like the rest of the photo very much.', '2004-05-30 21:39:52.000000', NULL, 1),
(742998, 78097, 489, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2004-05-30 21:40:15.000000', NULL, 1),
(743025, 78254, 9906, '<td valign="top">Love the vibrant colors!<br/>TC</td>', 'Love the vibrant colors!TC', '2004-05-30 22:07:36.000000', NULL, 1),
(743033, 78571, 10268, '<td valign="top">There''s a lot of noise/grain, but I like it.  The centering works for this.<br/> <br/>My only other complaint is that a brighter photo would have been nice.  6.</td>', 'There''s a lot of noise/grain, but I like it.  The centering works for this. My only other complaint is that a brighter photo would have been nice.  6.', '2004-05-30 22:19:10.000000', NULL, 1),
(743036, 78081, 10268, '<td valign="top">I don''t know about unusual, but it''s it''s beautiful.  5.</td>', 'I don''t know about unusual, but it''s it''s beautiful.  5.', '2004-05-30 22:21:41.000000', NULL, 1),
(743040, 78688, 10268, '<td valign="top">Interesting composition.  I don''t know if I like it or not, but it is interesting.<br/> <br/>And I don''t think it''s really an  unusual viewpoint either.  She''s maybe, in an unusual place, but the viewpoint is pretty normal.<br/> <br/>Anyway.  4.</td>', 'Interesting composition.  I don''t know if I like it or not, but it is interesting. And I don''t think it''s really an  unusual viewpoint either.  She''s maybe, in an unusual place, but the viewpoint is pretty normal. Anyway.  4.', '2004-05-30 22:26:34.000000', NULL, 1),
(743044, 78845, 10268, '<td valign="top">It looks like he''s on a turtle.  Even if he''s not, it''s kind of funny anyway.</td>', 'It looks like he''s on a turtle.  Even if he''s not, it''s kind of funny anyway.', '2004-05-30 22:28:34.000000', NULL, 1),
(743045, 78485, 10268, '<td valign="top">Doesn''t really look all that unusual to me, and I''m never really on the docks.<br/> <br/>But it''s really beautiful.</td>', 'Doesn''t really look all that unusual to me, and I''m never really on the docks. But it''s really beautiful.', '2004-05-30 22:31:33.000000', NULL, 1),
(743049, 78263, 22286, '<td valign="top">Beautiful shot.  Not that unusual a viewpoint, however.</td>', 'Beautiful shot.  Not that unusual a viewpoint, however.', '2004-05-30 22:35:54.000000', NULL, 1),
(743051, 77930, 22286, '<td valign="top">Great shot.  Great tone.  Very Unusual Viewpoint.  I love it!</td>', 'Great shot.  Great tone.  Very Unusual Viewpoint.  I love it!', '2004-05-30 22:39:42.000000', NULL, 1),
(743052, 78571, 22286, '<td valign="top">Great shot.  Good feel to it.  Very Unusual Viewpoint.</td>', 'Great shot.  Good feel to it.  Very Unusual Viewpoint.', '2004-05-30 22:40:04.000000', NULL, 1),
(743054, 78687, 22286, '<td valign="top">I like the idea.  I think I woul have prefered it off center... with more chair display and less aisle display.  The fuzziness bothers me.</td>', 'I like the idea.  I think I woul have prefered it off center... with more chair display and less aisle display.  The fuzziness bothers me.', '2004-05-30 22:41:21.000000', NULL, 1),
(743058, 78831, 22286, '<td valign="top">I like the window and the idea.  I think I would have tried to put the peak of the mountain in the center of one of the panes rather than on the wooden piece in the middle.</td>', 'I like the window and the idea.  I think I would have tried to put the peak of the mountain in the center of one of the panes rather than on the wooden piece in the middle.', '2004-05-30 22:44:08.000000', NULL, 1),
(743060, 78682, 22286, '<td valign="top">Great color!</td>', 'Great color!', '2004-05-30 22:45:46.000000', NULL, 1),
(743086, 78481, 16790, '<td valign="top">Brilliant!  Now there''s a new POV.... 10</td>', 'Brilliant!  Now there''s a new POV.... 10', '2004-05-30 23:07:46.000000', NULL, 1),
(743092, 78705, 8367, '<td valign="top">Great capture. I can''t offer anything for improvement. Looks perfect - 10!</td>', 'Great capture. I can''t offer anything for improvement. Looks perfect - 10!', '2004-05-30 23:17:37.000000', NULL, 1),
(743106, 78285, 8367, '<td valign="top">A beautiful capture. The blue sky with clouds sets off the beautiful markings perfectly.. Good choice.</td>', 'A beautiful capture. The blue sky with clouds sets off the beautiful markings perfectly.. Good choice.', '2004-05-30 23:30:16.000000', NULL, 1),
(743108, 78785, 8367, '<td valign="top">Cute capture and a great photo.</td>', 'Cute capture and a great photo.', '2004-05-30 23:32:14.000000', NULL, 1),
(743110, 77494, 12253, '<td valign="top">Excellent perspective shot.  One of my favorites!  On my monitor, the cow on the right is a bit too dark -- you can''t see eyes.(I don''t know if others can).  Might check it out on a few monitors--it might be alright, but if not, you would want to dodge a little there or lighten.  Very good overall!</td>', 'Excellent perspective shot.  One of my favorites!  On my monitor, the cow on the right is a bit too dark -- you can''t see eyes.(I don''t know if others can).  Might check it out on a few monitors--it might be alright, but if not, you would want to dodge a little there or lighten.  Very good overall!', '2004-05-30 23:33:31.000000', NULL, 1),
(743111, 78285, 12253, '<td valign="top">Very good perspective, great eye contact with the camera.  One of my fav''s for this challenge.</td>', 'Very good perspective, great eye contact with the camera.  One of my fav''s for this challenge.', '2004-05-30 23:34:20.000000', NULL, 1),
(743112, 78119, 12253, '<td valign="top">Good idea, and well shot.</td>', 'Good idea, and well shot.', '2004-05-30 23:34:35.000000', NULL, 1),
(743113, 78508, 12253, '<td valign="top">Not sure why this is an unusual viewpoint, though the colors are unusual.  But I don''t think this negative effect works well aesthetically.</td>', 'Not sure why this is an unusual viewpoint, though the colors are unusual.  But I don''t think this negative effect works well aesthetically.', '2004-05-30 23:35:52.000000', NULL, 1),
(743116, 78783, 12253, '<td valign="top">A nice veiwpoint and good use of desaturation.  However, IMHO the flower should be in focus.</td>', 'A nice veiwpoint and good use of desaturation.  However, IMHO the flower should be in focus.', '2004-05-30 23:36:54.000000', NULL, 1),
(743119, 77668, 12253, '<td valign="top">I assume this is mostly looking up, so we get the unusual viewpoint.  However, cutting off the top of the light tower makes the photo seem incomplete and loses the interest of that perspective.  The building in the lower right was not essential to this view either.</td>', 'I assume this is mostly looking up, so we get the unusual viewpoint.  However, cutting off the top of the light tower makes the photo seem incomplete and loses the interest of that perspective.  The building in the lower right was not essential to this view either.', '2004-05-30 23:38:20.000000', NULL, 1),
(743120, 78838, 8891, '<td valign="top">wow....oh what the heck....BIG WOW!</td>', 'wow....oh what the heck....BIG WOW!', '2004-05-30 23:38:52.000000', NULL, 1),
(743121, 78687, 12253, '<td valign="top">An interesting perspective, but IMIO, this would have worked if the something were in focus.  As is, there''s nothing for the eye to grab a hold of.</td>', 'An interesting perspective, but IMIO, this would have worked if the something were in focus.  As is, there''s nothing for the eye to grab a hold of.', '2004-05-30 23:39:32.000000', NULL, 1),
(743124, 77923, 12253, '<td valign="top">Well shot, but to me these types of textual shots lack the aesthetics of photographing the "real world"</td>', 'Well shot, but to me these types of textual shots lack the aesthetics of photographing the "real world"', '2004-05-30 23:41:13.000000', NULL, 1),
(743126, 78908, 8891, '<td valign="top">As I crane my neck to see what''s going on I''m wondering why the landscape orientiation....ahh there''s that crick in my neck again....thanks! LOL!.  Really fine, rotate please.</td>', 'As I crane my neck to see what''s going on I''m wondering why the landscape orientiation....ahh there''s that crick in my neck again....thanks! LOL!.  Really fine, rotate please.', '2004-05-30 23:41:36.000000', NULL, 1),
(743135, 78704, 12253, '<td valign="top">Well done shot and good unusual viewpoint.</td>', 'Well done shot and good unusual viewpoint.', '2004-05-30 23:53:02.000000', NULL, 1),
(743136, 77930, 12253, '<td valign="top">I don''t normally like gun photos, but this one is well done, well acted, and I love the background and sepia tone.  May be a winner!</td>', 'I don''t normally like gun photos, but this one is well done, well acted, and I love the background and sepia tone.  May be a winner!', '2004-05-30 23:53:42.000000', NULL, 1),
(743190, 78332, 6771, '<td valign="top">This is a very well done photo, not to mention the humor it has.  Very good grey tones</td>', 'This is a very well done photo, not to mention the humor it has.  Very good grey tones', '2004-05-31 00:35:59.000000', NULL, 1),
(743192, 78005, 6771, '<td valign="top">Great colors and focus, even through the glass.  got them looking right at ya.  I like the DOF</td>', 'Great colors and focus, even through the glass.  got them looking right at ya.  I like the DOF', '2004-05-31 00:37:44.000000', NULL, 1),
(743202, 78538, 6771, '<td valign="top">Very awesome perspective.  Love the way I am drawn back to the far area of this.  I would have gotten rid of the bird overhead, it is distracting.  Keep looking at it going "what the F is that?".  This would look real great with just that color of blue backgraound sans cloud.  Great work though</td>', 'Very awesome perspective.  Love the way I am drawn back to the far area of this.  I would have gotten rid of the bird overhead, it is distracting.  Keep looking at it going "what the F is that?".  This would look real great with just that color of blue backgraound sans cloud.  Great work though', '2004-05-31 00:41:44.000000', NULL, 1),
