(748294, 78838, 9441, '<td valign="top">Wow<br/>very cool shot!<br/>the colors just pop!<br/>I love the way the bug stands out boldly against the blurred background.  Nice job!!</td>', 'Wowvery cool shot!the colors just pop!I love the way the bug stands out boldly against the blurred background.  Nice job!!', '2004-06-03 04:25:04.000000', NULL, 0),
(748940, 78119, 22186, '<td valign="top">What a beautiful picture. The eye''s color is so extraordinary. Keep up the nice work. Congratulations!<b>text</b></td>', 'What a beautiful picture. The eye''s color is so extraordinary. Keep up the nice work. Congratulations!text', '2004-06-03 15:57:41.000000', NULL, 0),
